import sys

def generate_points(n, k):
    # If k is too small, it's impossible to cause TLE
    if k <= n:
        return "no solution"

    # Generate points in a grid pattern to ensure the inner loop runs a lot
    points = []
    for i in range(n):
        for j in range(n):
            if i != j:  # Ensure all points are distinct
                points.append((i, j))

    return points

# Read input
n, k = map(int, sys.stdin.readline().split())

# Generate and print the points
result = generate_points(n, k)
if result == "no solution":
    print(result)
else:
    for point in result:
        print(f"{point[0]} {point[1]}")
